def f(n, v1):
    n = 0
    i = 0
    k = 0
    j = 0
    l = 0
    v1 = 0
    v2 = 0
    v3 = 0
    v4 = 0
    v5 = 0
    while l < n:
        if ( not (l%8)):
            v5 = v5 + 1
        else:
            if( not (l%7))
	    v1 = v1 + 1
        if ( not (l%6)):
            v2 = v2 + 1
        else:
            if( not (l%5))
	    v3 = v3 + 1
        if ( not (l%4)):
            v4 = v4 + 1
        else:
            if( not (l%3))
	    i = i + 1
        if ( not (l%2)):
            j = j+1
        else:
            k = k+1
        l = l+1
        assert (i+j+k+v1+v2+v3+v4+v5) == l
    return
